import unittest
from count import normalize_count

class CountTests(unittest.TestCase):
    def test_zero(self): self.assertEqual(normalize_count(0), 0)
    def test_positive(self): self.assertEqual(normalize_count(3), 3)
    def test_negative(self):
        with self.assertRaises(ValueError): normalize_count(-1)

if __name__ == "__main__": unittest.main()
